// Real AppKit menu/window and original UI; synthetic controller completion and
// compile-time termination recorder. Does not claim actual installer exit.
#import "InstallerApplication.h"
@interface TestOwner:NSObject<SEPInstallerPrivateTransport>
@property(nonatomic,strong)NSMutableArray *operations,*callbacks;
@property(nonatomic,copy)void(^termination)(NSInteger,BOOL);
@end
@implementation TestOwner
- (instancetype)init{if((self=[super init])){_operations=[NSMutableArray new];_callbacks=[NSMutableArray new];}return self;}
- (void)requestOperation:(NSString*)operation input:(NSDictionary*)input completion:(void(^)(NSDictionary*))completion {[_operations addObject:@{@"operation":operation,@"input":input}];[_callbacks addObject:[completion copy]];}
- (void)observeTermination:(void(^)(NSInteger,BOOL))observer{_termination=[observer copy];}
- (void)reply:(NSDictionary*)value{void(^callback)(NSDictionary*)=_callbacks.lastObject;callback(value);}
- (NSUInteger)count:(NSString*)name{NSUInteger count=0;for(NSDictionary *r in _operations)if([r[@"operation"]isEqual:name])count++;return count;}
@end
@interface TestOpener:NSObject<SEPInstallerApplicationOpener>@end
@implementation TestOpener
- (void)openInstalledApplication:(NSURL*)url completion:(void(^)(BOOL))completion{(void)url;completion(NO);}
@end
static void Pump(double seconds){NSDate*d=[NSDate dateWithTimeIntervalSinceNow:seconds];do{[[NSRunLoop mainRunLoop]runMode:NSDefaultRunLoopMode beforeDate:[NSDate dateWithTimeIntervalSinceNow:0.002]];}while(d.timeIntervalSinceNow>0);}
static void Check(BOOL pass,NSString*code){if(!pass)@throw[NSException exceptionWithName:@"ASSERTION" reason:code userInfo:nil];}
static NSView *Find(NSView*v,NSString*s){if([v.identifier isEqual:s])return v;for(NSView*c in v.subviews){NSView*r=Find(c,s);if(r)return r;}return nil;}
static NSMenuItem *Quit(void){for(NSMenuItem*root in NSApp.mainMenu.itemArray)for(NSMenuItem*item in root.submenu.itemArray)if([item.keyEquivalent isEqual:@"q"])return item;return nil;}
static NSDictionary*Fixture(void){TestOwner*owner=[TestOwner new];SEPInstallerUI*ui=[[SEPInstallerUI alloc]initWithTransport:owner opener:[TestOpener new]];NSMutableArray*termination=[NSMutableArray new];SEPInstallerApplication*app=[[SEPInstallerApplication alloc]initWithUI:ui terminationRequest:^{[termination addObject:@YES];}];[app installMenu];[ui present];[owner reply:@{@"status":@"pass",@"phase":@"recovery-list",@"recoveries":@[]}];Pump(0.02);[owner reply:@{@"status":@"pass",@"phase":@"preview",@"preview":@{@"planHash":[@"a" stringByPaddingToLength:64 withString:@"a" startingAtIndex:0],@"transactionId":[@"b" stringByPaddingToLength:32 withString:@"b" startingAtIndex:0],@"target":@"/Users/synthetic/Applications/DSH SEP.app",@"dataRoot":@"/Users/synthetic/Library/Application Support/SEP",@"entries":@1,@"totalBytes":@1,@"createApplications":@YES}}];Pump(0.02);return@{@"owner":owner,@"ui":ui,@"app":app,@"termination":termination};}
static void MenuQuit(NSDictionary*f){NSMenuItem*q=Quit();Check(q&&q.target==f[@"app"]&&q.action==@selector(requestQuit:),@"Quit must target installer delegate");[q.menu performActionForItemAtIndex:[q.menu indexOfItem:q]];Pump(0.02);}
static void Closed(NSDictionary*f){TestOwner*owner=f[@"owner"];[owner reply:@{@"status":@"pass",@"phase":@"closed",@"resourcesReleased":@YES}];Pump(0.02);owner.termination(0,NO);Pump(0.03);}
static void Run(NSString*name,void(^body)(NSDictionary*),NSMutableArray*rows){NSDictionary*f=Fixture();@try{body(f);[rows addObject:@{@"name":name,@"status":@"pass"}];}@catch(NSException*e){[rows addObject:@{@"name":name,@"status":@"fail",@"code":e.reason?:@"ASSERTION"}];}@finally{SEPInstallerUI*ui=f[@"ui"];if(ui.window.attachedSheet)[NSApp endSheet:ui.window.attachedSheet returnCode:NSAlertSecondButtonReturn];[ui.window orderOut:nil];NSApp.mainMenu=nil;}}
int main(void){@autoreleasepool{[NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyAccessory];NSMutableArray*rows=[NSMutableArray new];
 Run(@"real Quit menu routes to owned UI close instead of unconditional terminate",^(NSDictionary*f){MenuQuit(f);Check([(TestOwner*)f[@"owner"]count:@"close"]==1&&[f[@"termination"]count]==0,@"menu bypassed close gate");},rows);
 Run(@"application termination request is refused until actual UI release",^(NSDictionary*f){SEPInstallerApplication*app=f[@"app"];Check([app applicationShouldTerminate:NSApp]==NSTerminateCancel,@"quit allowed before release");Check([(TestOwner*)f[@"owner"]count:@"close"]==1,@"idle quit did not request close");},rows);
 Run(@"busy accepted install refuses parallel close and app termination",^(NSDictionary*f){SEPInstallerUI*ui=f[@"ui"];[(NSButton*)Find(ui.window.contentView,@"install")performClick:nil];Pump(0.03);Check(ui.window.attachedSheet!=nil,@"real confirmation absent");[NSApp endSheet:ui.window.attachedSheet returnCode:NSAlertFirstButtonReturn];Pump(0.05);Check([(TestOwner*)f[@"owner"]count:@"confirm"]==1,@"confirm not accepted");SEPInstallerApplication*app=f[@"app"];Check([app applicationShouldTerminate:NSApp]==NSTerminateCancel,@"busy quit allowed");Check([(TestOwner*)f[@"owner"]count:@"close"]==0&&ui.window.isVisible,@"busy owner closed");},rows);
 Run(@"repeated Quit does not dispatch a second controller close",^(NSDictionary*f){MenuQuit(f);MenuQuit(f);Check([(TestOwner*)f[@"owner"]count:@"close"]==1,@"duplicate close");},rows);
 Run(@"closed receipt alone still rejects application termination",^(NSDictionary*f){MenuQuit(f);TestOwner*owner=f[@"owner"];[owner reply:@{@"status":@"pass",@"phase":@"closed",@"resourcesReleased":@YES}];Pump(0.02);Check([(SEPInstallerApplication*)f[@"app"]applicationShouldTerminate:NSApp]==NSTerminateCancel&&[f[@"termination"]count]==0,@"receipt alone released process");},rows);
 Run(@"same UI release requests final termination once and permits Now",^(NSDictionary*f){MenuQuit(f);Closed(f);Check([f[@"termination"]count]==1,@"true close did not request final terminate exactly once");Check([(SEPInstallerApplication*)f[@"app"]applicationShouldTerminate:NSApp]==NSTerminateNow,@"true release still blocked");},rows);
 Run(@"abnormal child exit stays blocked and keeps application alive",^(NSDictionary*f){MenuQuit(f);TestOwner*owner=f[@"owner"];[owner reply:@{@"status":@"blocked",@"phase":@"blocked",@"code":@"SEP_INSTALLER_CLEANUP_UNCONFIRMED"}];Pump(0.02);owner.termination(1,YES);Pump(0.02);Check([(SEPInstallerApplication*)f[@"app"]applicationShouldTerminate:NSApp]==NSTerminateCancel&&[f[@"termination"]count]==0,@"abnormal exit promoted");},rows);
 Run(@"unrelated and last-window events do not bypass the release gate",^(NSDictionary*f){NSWindow*other=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,30,30) styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];[NSNotificationCenter.defaultCenter postNotificationName:NSWindowWillCloseNotification object:other];Pump(0.01);Check([f[@"termination"]count]==0,@"unrelated window terminated installer");Check(![(SEPInstallerApplication*)f[@"app"]applicationShouldTerminateAfterLastWindowClosed:NSApp],@"last window bypassed owner");},rows);
 NSUInteger passed=0;for(NSDictionary*r in rows)if([r[@"status"]isEqual:@"pass"])passed++;NSDictionary*result=@{@"schema":@1,@"scope":@"actual AppKit controls/delegate; synthetic owner and compile-time termination recorder; not actual product exit",@"definitions":@8,@"passed":@(passed),@"failed":@(rows.count-passed),@"status":passed==rows.count?@"pass":@"fail",@"results":rows,@"productInstalled":@NO};NSData*json=[NSJSONSerialization dataWithJSONObject:result options:NSJSONWritingPrettyPrinted error:nil];fwrite(json.bytes,1,json.length,stdout);fputc('\n',stdout);return passed==rows.count?0:1;}}
